/// Every `menu()` declared by a vendored `.dbd`, keyed by its EPICS name.
///
/// This is the table `get_enum_strs` answers a `DBF_MENU` field from: the
/// field's [`FieldDesc::menu`] already points at its choices, and this map
/// exists for the by-name lookups (`.db` loading, `dbpr`).
pub fn menu_choices(menu: &str) -> Option<&'static [&'static str]> {
    Some(match menu {
        "aSubEFLG" => MENU_A_SUB_EFLG,
        "aSubLFLG" => MENU_A_SUB_LFLG,
        "aaiPOST" => MENU_AAI_POST,
        "aaoPOST" => MENU_AAO_POST,
        "acalcoutDOPT" => MENU_ACALCOUT_DOPT,
        "acalcoutINAP" => MENU_ACALCOUT_INAP,
        "acalcoutINAV" => MENU_ACALCOUT_INAV,
        "acalcoutOOPT" => MENU_ACALCOUT_OOPT,
        "acalcoutSIZE" => MENU_ACALCOUT_SIZE,
        "acalcoutWAIT" => MENU_ACALCOUT_WAIT,
        "aoOIF" => MENU_AO_OIF,
        "asynAUTOCONNECT" => MENU_ASYN_AUTOCONNECT,
        "asynCONNECT" => MENU_ASYN_CONNECT,
        "asynENABLE" => MENU_ASYN_ENABLE,
        "asynEOMREASON" => MENU_ASYN_EOMREASON,
        "asynFMT" => MENU_ASYN_FMT,
        "asynINTERFACE" => MENU_ASYN_INTERFACE,
        "asynTMOD" => MENU_ASYN_TMOD,
        "asynTRACE" => MENU_ASYN_TRACE,
        "bufferingALG" => MENU_BUFFERING_ALG,
        "calcoutDOPT" => MENU_CALCOUT_DOPT,
        "calcoutINAV" => MENU_CALCOUT_INAV,
        "calcoutOOPT" => MENU_CALCOUT_OOPT,
        "compressALG" => MENU_COMPRESS_ALG,
        "dfanoutSELM" => MENU_DFANOUT_SELM,
        "fanoutSELM" => MENU_FANOUT_SELM,
        "gpibACMD" => MENU_GPIB_ACMD,
        "gpibUCMD" => MENU_GPIB_UCMD,
        "histogramCMD" => MENU_HISTOGRAM_CMD,
        "ipDRTO" => MENU_IP_DRTO,
        "longoutOOPT" => MENU_LONGOUT_OOPT,
        "menuAlarmSevr" => MENU_ALARM_SEVR,
        "menuAlarmStat" => MENU_ALARM_STAT,
        "menuConvert" => MENU_CONVERT,
        "menuFtype" => MENU_FTYPE,
        "menuIvoa" => MENU_IVOA,
        "menuOmsl" => MENU_OMSL,
        "menuPini" => MENU_PINI,
        "menuPost" => MENU_POST,
        "menuPriority" => MENU_PRIORITY,
        "menuScan" => MENU_SCAN,
        "menuSimm" => MENU_SIMM,
        "menuYesNo" => MENU_YES_NO,
        "scalcoutDOPT" => MENU_SCALCOUT_DOPT,
        "scalcoutINAP" => MENU_SCALCOUT_INAP,
        "scalcoutINAV" => MENU_SCALCOUT_INAV,
        "scalcoutOOPT" => MENU_SCALCOUT_OOPT,
        "scalcoutWAIT" => MENU_SCALCOUT_WAIT,
        "selSELM" => MENU_SEL_SELM,
        "seqSELM" => MENU_SEQ_SELM,
        "serialBAUD" => MENU_SERIAL_BAUD,
        "serialDBIT" => MENU_SERIAL_DBIT,
        "serialFCTL" => MENU_SERIAL_FCTL,
        "serialIX" => MENU_SERIAL_IX,
        "serialMCTL" => MENU_SERIAL_MCTL,
        "serialPRTY" => MENU_SERIAL_PRTY,
        "serialSBIT" => MENU_SERIAL_SBIT,
        "sseqLNKV" => MENU_SSEQ_LNKV,
        "sseqSELM" => MENU_SSEQ_SELM,
        "sseqWAIT" => MENU_SSEQ_WAIT,
        "stringinPOST" => MENU_STRINGIN_POST,
        "stringoutPOST" => MENU_STRINGOUT_POST,
        "swaitDOPT" => MENU_SWAIT_DOPT,
        "swaitINAP" => MENU_SWAIT_INAP,
        "swaitINAV" => MENU_SWAIT_INAV,
        "swaitOOPT" => MENU_SWAIT_OOPT,
        "transformCOPT" => MENU_TRANSFORM_COPT,
        "transformIAV" => MENU_TRANSFORM_IAV,
        "transformIVLA" => MENU_TRANSFORM_IVLA,
        "waveformPOST" => MENU_WAVEFORM_POST,
        _ => return None,
    })
}

